# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLENİN ÖGELERİ TABLOSU (YÖN KURALI: YÜKLEM → ÖZNE → NESNE)</text>\n  <rect x="25" y="55" width="315" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Temel Ögeler (Yüklem ve Özne)</text>\n  <text x="45" y="105" font-size="11.5" font-weight="bold" fill="#1e40af">• YÜKLEM (İlk bulunan öge):</text>\n  <text x="55" y="123" font-size="11" fill="#334155">İş, oluş, hareket veya yargı bildirir. Soru sorulmaz!</text>\n  <text x="45" y="150" font-size="11.5" font-weight="bold" fill="#1e40af">• ÖZNE (İkinci bulunan öge):</text>\n  <text x="55" y="168" font-size="11" fill="#334155">Yüklemin bildirdiği işi yapandır. Soruları: Kim? / Ne?</text>\n  <text x="55" y="192" font-size="11" fill="#475569">- Gerçek (Açık) Özne / Gizli Özne (Öge sayısına katılmaz!)</text>\n  <text x="55" y="212" font-size="11" fill="#475569">- Sözde Özne (Edilgen çatılı fiillerde işten etkilenen)</text>\n  <rect x="355" y="55" width="320" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Yardımcı Ögeler (Nesne, Yer, Zarf)</text>\n  <text x="375" y="105" font-size="11.5" font-weight="bold" fill="#166534">• NESNE (İşten etkilenen):</text>\n  <text x="385" y="123" font-size="11" fill="#334155">- Belirtili (-ı/-i/-u/-ü): Neyi? Kimi? Nereyi?</text>\n  <text x="385" y="141" font-size="11" fill="#334155">- Belirtisiz (Eksiz): (Özneden sonra) Ne?</text>\n  <text x="375" y="166" font-size="11.5" font-weight="bold" fill="#166534">• YER TAMLAYICISI (-e / -de / -den):</text>\n  <text x="385" y="184" font-size="11" fill="#334155">Kime, kimde, kimden; neye, nerede, nereden?</text>\n  <text x="375" y="208" font-size="11.5" font-weight="bold" fill="#166534">• ZARF TAMLAYICISI:</text>\n  <text x="385" y="226" font-size="11" fill="#334155">Ne zaman, nasıl, niçin, ne kadar, neyle, kiminle?</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLEDE VURGU, ARA SÖZ VE CÜMLE DIŞI UNSUR</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Cümlede Vurgunun Yeri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Fiil Cümlesinde: Yüklemden hemen önceki ögededir.</text>\n  <text x="65" y="126" font-size="11" fill="#475569">("Atatürk, kongreyi ANKARA\'DA topladı." → Yer T.)</text>\n  <text x="55" y="150" font-size="11.5" fill="#334155">• İsim Cümlesinde ve Yüklem Baştaysa: Yüklemdedir.</text>\n  <text x="55" y="174" font-size="11.5" fill="#334155">• \'mi\' soru eki ve \'de/da\' bağlacı: Kendinden önceki</text>\n  <text x="65" y="192" font-size="11" fill="#475569">ögeye vurguyu çeker.</text>\n  <text x="55" y="216" font-size="11.5" fill="#334155">• Soru sözcüğü varsa: Vurgu soru sözcüğündedir.</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Ara Söz ve Cümle Dışı Unsur (CDU)</text>\n  <text x="380" y="108" font-size="11.5" font-weight="bold" fill="#9d174d">• Ara Söz (İki virgül veya iki kısa çizgi arası):</text>\n  <text x="385" y="128" font-size="11" fill="#334155">"Ankara\'ya, başkentimize, dün gittik." (Yer T. açıklayıcısı)</text>\n  <text x="380" y="156" font-size="11.5" font-weight="bold" fill="#9d174d">• Ara Cümle / Cümle Dışı Unsur:</text>\n  <text x="385" y="176" font-size="11" fill="#334155">Hiçbir ögenin açıklayıcısı olmayan ara cümleler,</text>\n  <text x="385" y="196" font-size="11" fill="#334155">bağlaçlar, ünlemler ve hitaplar ("Öğretmenler!")</text>\n  <text x="385" y="216" font-size="11" font-weight="bold" fill="#be185d">Cümle Dışı Unsur (CDU) kabul edilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ATATÜRK VE EĞİTİM METNİ — CÜMLEDE ANLAM İLİŞKİLERİ</text>\n  <rect x="30" y="55" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Atatürk\'ün Eğitim Vizyonu</text>\n  <text x="130" y="108" text-anchor="middle" font-size="11" fill="#334155">• Maarif Kongresi (Temmuz 1921):</text>\n  <text x="130" y="126" text-anchor="middle" font-size="10.5" fill="#475569">Cephede savaş sürerken Ankara\'da</text>\n  <text x="130" y="144" text-anchor="middle" font-size="10.5" fill="#475569">eğitim kongresi toplamıştır.</text>\n  <text x="130" y="172" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">"Öğretmenler! Yeni nesil</text>\n  <text x="130" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">sizin eseriniz olacaktır."</text>\n  <text x="130" y="218" text-anchor="middle" font-size="10.5" fill="#334155">Cehaletle savaş = Vatan savunması</text>\n  <rect x="250" y="55" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Neden - Amaç - Koşul</text>\n  <text x="265" y="108" font-size="11" fill="#334155">• Neden-Sonuç (-dığı için):</text>\n  <text x="265" y="126" font-size="10.5" fill="#475569">İki yargı da gerçekleşmiştir.</text>\n  <text x="265" y="152" font-size="11" fill="#334155">• Amaç-Sonuç (-mak amacıyla):</text>\n  <text x="265" y="170" font-size="10.5" fill="#475569">Hedef bildirir (gerçekleşmesi belirsiz).</text>\n  <text x="265" y="196" font-size="11" fill="#334155">• Koşul-Sonuç (-sa/-se, -dıkça):</text>\n  <text x="265" y="214" font-size="10.5" fill="#475569">Şarta bağlılık bildirir.</text>\n  <rect x="470" y="55" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dinleme Stratejileri</text>\n  <text x="485" y="110" font-size="11" fill="#334155">• Not Alarak Dinleme: Önemli</text>\n  <text x="495" y="126" font-size="10.5" fill="#475569">kavram ve tarihleri kaydetme.</text>\n  <text x="485" y="152" font-size="11" fill="#334155">• Empati Kurarak Dinleme:</text>\n  <text x="495" y="168" font-size="10.5" fill="#475569">Konuşmacının yerine kendini koyma.</text>\n  <text x="485" y="194" font-size="11" fill="#334155">• Eleştirel / Seçici Dinleme:</text>\n  <text x="495" y="210" font-size="10.5" fill="#475569">Ana ve yardımcı fikirleri süzme.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
